package reach

import (
	"bufio"
	_ "embed"
	"net/netip"
	"slices"
	"strings"
	"sync"
)

// chnroutes lists mainland China's address blocks, generated by scripts/gen-chnroutes.sh from
// APNIC's public delegation statistics; its header names the file date.
//
//go:embed chnroutes.txt
var chnroutes string

type addrRange struct{ first, last netip.Addr }

var mainlandRanges = sync.OnceValue(func() []addrRange {
	var out []addrRange
	sc := bufio.NewScanner(strings.NewReader(chnroutes))
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		p, err := netip.ParsePrefix(line)
		if err != nil {
			panic("reach: chnroutes.txt: " + err.Error())
		}
		p = p.Masked()
		out = append(out, addrRange{p.Addr(), lastAddr(p)})
	}
	slices.SortFunc(out, func(a, b addrRange) int { return a.first.Compare(b.first) })
	return out
})

// lastAddr is the highest address in p, which must be masked.
func lastAddr(p netip.Prefix) netip.Addr {
	b := p.Addr().AsSlice()
	for i := p.Bits(); i < len(b)*8; i++ {
		b[i/8] |= 0x80 >> (i % 8)
	}
	a, _ := netip.AddrFromSlice(b)
	return a
}

// InMainland reports whether ip belongs to a block registered to mainland China.
func InMainland(ip netip.Addr) bool {
	ip = ip.Unmap()
	if !ip.IsValid() {
		return false
	}
	ranges := mainlandRanges()
	// The last range starting at or before ip is the only one that can hold it: the blocks do not overlap.
	i, _ := slices.BinarySearchFunc(ranges, ip, func(r addrRange, ip netip.Addr) int {
		if r.first.Compare(ip) <= 0 {
			return -1
		}
		return 1
	})
	if i == 0 {
		return false
	}
	r := ranges[i-1]
	return r.first.Is4() == ip.Is4() && ip.Compare(r.last) <= 0
}
